sys_script_include.script:
var LOAEvaluationVersionService = Class.create();
LOAEvaluationVersionService.prototype = {
    initialize: function() {
        this.TABLE = 'x_gegis_ins_policy_loa_evaluation';
        this.LINE_TABLE = 'x_gegis_ins_policy_submission_line';

        // loa_evaluation.evaluation_trigger is ITS OWN pre-existing local choice
        // (initial_evaluation/grant_change/manual_reevaluation/exposure_change/
        // quote_change/intake_change) - a different, older taxonomy than the new
        // x_gegis_ins_policy_uw_trigger_reason.code catalog UWTriggerReasonResolver
        // resolves against. The constraints forbid touching existing fields/choices,
        // so rather than adding a trigger_reason reference column to this table,
        // this map translates the shared code onto the closest existing
        // evaluation_trigger value. ASSUMPTION, documented here as the single place
        // it happens: initial_assignment/underwriter_reassigned/manual_correction
        // have no exact equivalent in the old list, so they map to the nearest
        // fit (initial_evaluation / manual_reevaluation / manual_reevaluation).
        var C = x_gegis_ins_policy.Constants.CHOICE.UW_TRIGGER_REASON_CODE;
        var map = {};
        map[C.INITIAL_SUBMISSION]     = 'initial_evaluation';
        map[C.TIV_CHANGE]             = 'exposure_change';
        map[C.PROPERTY_COUNT_CHANGE]  = 'exposure_change';
        map[C.RENEWAL]                = 'intake_change';
        map[C.ENDORSEMENT]            = 'intake_change';
        map[C.INITIAL_ASSIGNMENT]     = 'initial_evaluation';
        map[C.UNDERWRITER_REASSIGNED] = 'manual_reevaluation';
        map[C.MANUAL_CORRECTION]      = 'manual_reevaluation';
        this.CODE_TO_EVALUATION_TRIGGER = map;
    },

    /**
     * Create the next loa_evaluation header row for a submission_line.
     *
     *   1. Look up the current active=true row for this submission_line (there
     *      is at most one) to get its version number and evaluation_status.
     *   2. Insert version = (that version + 1), or 1 if none exists yet, with
     *      active = true.
     *   3. Flip the previous active row to false, in the SAME call.
     *
     * Result columns (authority_tier, is_authorized, checks_count, breach_count,
     * decision, decided_by/on, ...) are intentionally left untouched - HOOK POINT
     * for the future evaluation flow, which reads the row this method just
     * created (active=true for the submission_line) and populates them.
     *
     * @param submissionLineId sys_id of x_gegis_ins_policy_submission_line (required)
     * @param triggerReasonId sys_id of x_gegis_ins_policy_uw_trigger_reason,
     *        e.g. from UWTriggerReasonResolver.resolve() (required)
     * @return sys_id of the newly inserted row, or '' when the call was refused
     */
    createNextVersion: function(submissionLineId, triggerReasonId) {
        if (!submissionLineId || !triggerReasonId) {
            gs.error('[LOAEvaluationVersionService] createNextVersion refused - submissionLineId=' +
                submissionLineId + ' triggerReasonId=' + triggerReasonId +
                ' (both are required; a header row with a null/broken trigger_reason is not created)');
            return '';
        }

        var line = new GlideRecord(this.LINE_TABLE);
        if (!line.get(submissionLineId)) {
            gs.error('[LOAEvaluationVersionService] submission_line ' + submissionLineId + ' not found');
            return '';
        }

        var reason = new GlideRecord('x_gegis_ins_policy_uw_trigger_reason');
        if (!reason.get(triggerReasonId)) {
            gs.error('[LOAEvaluationVersionService] uw_trigger_reason ' + triggerReasonId + ' not found');
            return '';
        }
        var evaluationTrigger = this.CODE_TO_EVALUATION_TRIGGER[String(reason.getValue('code'))];
        if (!evaluationTrigger) {
            gs.error('[LOAEvaluationVersionService] no evaluation_trigger mapping for code=' +
                reason.getValue('code') + ' - defaulting to manual_reevaluation, update the map');
            evaluationTrigger = 'manual_reevaluation';
        }

        var nextVersion = 1;
        var previousStatus = '';
        var prev = new GlideRecord(this.TABLE);
        prev.addQuery('submission_line', submissionLineId);
        prev.addQuery('active', true);
        prev.query();
        if (prev.next()) {
            nextVersion = (parseInt(prev.getValue('version'), 10) || 1) + 1;
            previousStatus = String(prev.getValue('evaluation_status'));
            prev.setValue('active', false);
            prev.update();
        }

        var gr = new GlideRecord(this.TABLE);
        gr.initialize();
        gr.setValue('submission', line.getValue('submission'));
        gr.setValue('submission_line', submissionLineId);
        gr.setValue('line_of_business', line.getValue('line_of_business'));
        gr.setValue('version', nextVersion);
        gr.setValue('active', true);
        gr.setValue('evaluation_trigger', evaluationTrigger);
        gr.setValue('evaluated_on', new GlideDateTime());
        // Snapshot WHO was being evaluated at this version, independent of
        // matched_grant (only populated on a match, never on a breach) and
        // independent of submission_line.underwriter (would drift if the
        // line is later reassigned - this historical version must keep
        // pointing at the underwriter who was actually checked).
        var underwriterId = line.getValue('underwriter');
        if (underwriterId)
            gr.setValue('evaluated_underwriter', underwriterId);
        if (previousStatus)
            gr.setValue('previous_evaluation_status', previousStatus);
        // evaluation_status keeps its dictionary default ('pending'). authority_tier,
        // is_authorized, checks_count, breach_count, decision*, decided_by/on: HOOK
        // POINT for the future evaluation flow. Left untouched here on purpose.

        var newId = gr.insert();
        if (!newId) {
            gs.error('[LOAEvaluationVersionService] insert REFUSED for submission_line=' +
                submissionLineId + ' v' + nextVersion + ' trigger_reason=' + triggerReasonId +
                ' - check ACLs/mandatory fields on ' + this.TABLE);
            return '';
        }
        return newId;
    },

    // =====================================================================
    // READ-ONLY RETRIEVERS - added for the playbook activities that render
    // the Letter of Authority panel. Pure reads: no insert/update, so they
    // cannot break createNextVersion above.
    //
    // Same convention as UWGuidelineVersionService's own retrievers (see the
    // long comment there for why): resolve the caller-facing submission
    // NUMBER to sys_id(s) first, walk children by addQuery, return a plain
    // {success, message, lines:[...]} object of camelCase keys - this app
    // has no {success,data,message} envelope standard for a multi-record
    // retriever to match, so both script includes deliberately use the same
    // documented shape rather than inventing two different ones.
    //
    // submissionNumber -> submission_line(s): loa_evaluation.submission_line
    // is its own column (see x_gegis_ins_policy_loa_evaluation_submission_
    // _line), and a submission can carry more than one LOB/line (submission
    // _line.submission FK). So, exactly as for UW Guidelines, both methods
    // return every line grouped separately rather than guessing which one
    // line the caller wants.
    //
    // "Latest" here means active=true, NOT is_latest - loa_evaluation uses
    // its own pre-existing version+active shape (see the class description
    // and createNextVersion above), so getLatestLoaEvaluationForSubmission
    // reads active=true rather than an is_latest column that does not exist
    // on this table.
    // =====================================================================

    /**
     * Full loa_evaluation history (every version, not just active) for
     * every submission_line under a submission, for the version dropdown.
     * Each version is fully nested with its loa_evaluation_line children,
     * per the "Why this submission exceeds authority" mockup.
     *
     * @param submissionNumber x_gegis_ins_policy_submission.number
     * @return {success, message, lines:[{submissionLineId, lineOfBusiness,
     *          versions:[{sysId, number, version, isActive,
     *          evaluationStatus, evaluationStatusCode, evaluationTrigger,
     *          evaluationTriggerCode, evaluatedOn, evaluatedUnderwriter,
     *          authorityTier, authorityTierCode, isAuthorized,
     *          requiresReferral, referredToTier, message, checksCount,
     *          breachCount, maxUtilisationPercent, decidedBy, decidedOn,
     *          decisionNotes, createdOn,
     *          evaluationLines:[{sysId, metricLabel, exposureAmount,
     *          exposureCount, limitAmountSnapshot, limitCountSnapshot,
     *          utilisationPercent, result, resultCode, breachAmount,
     *          breachReason, currency}]}]}]}
     */
    getLoaEvaluationsForSubmission: function(submissionNumber) {
        if (!submissionNumber)
            return { success: false, message: 'submissionNumber is required', lines: [] };

        var lineIds = this._resolveSubmissionLines(submissionNumber);
        if (!lineIds.length)
            return { success: false, message: 'No submission_line found for submission ' + submissionNumber, lines: [] };

        var lines = [];
        for (var i = 0; i < lineIds.length; i++)
            lines.push(this._buildLineEvaluations(lineIds[i], false));

        return { success: true, message: '', lines: lines };
    },

    /**
     * Convenience wrapper most callers actually want: same shape as
     * getLoaEvaluationsForSubmission, but each line carries only its
     * active=true evaluation, as `latestVersion` (singular), instead of the
     * full `versions` array.
     *
     * @param submissionNumber x_gegis_ins_policy_submission.number
     * @return {success, message, lines:[{submissionLineId, lineOfBusiness,
     *          latestVersion:{...same shape as one entry in versions[]...}|null}]}
     */
    getLatestLoaEvaluationForSubmission: function(submissionNumber) {
        if (!submissionNumber)
            return { success: false, message: 'submissionNumber is required', lines: [] };

        var lineIds = this._resolveSubmissionLines(submissionNumber);
        if (!lineIds.length)
            return { success: false, message: 'No submission_line found for submission ' + submissionNumber, lines: [] };

        var lines = [];
        for (var i = 0; i < lineIds.length; i++)
            lines.push(this._buildLineEvaluations(lineIds[i], true));

        return { success: true, message: '', lines: lines };
    },

    /** submission NUMBER -> every submission_line sys_id under it. */
    _resolveSubmissionLines: function(submissionNumber) {
        var ids = [];
        var sub = new GlideRecord('x_gegis_ins_policy_submission');
        sub.addQuery('number', String(submissionNumber));
        sub.setLimit(1);
        sub.query();
        if (!sub.next())
            return ids;

        var line = new GlideRecord(this.LINE_TABLE);
        line.addQuery('submission', sub.getUniqueValue());
        line.query();
        while (line.next())
            ids.push(line.getUniqueValue());
        return ids;
    },

    /**
     * One submission_line's loa_evaluation history (or just its active row,
     * when latestOnly is true), each fully nested with its
     * loa_evaluation_line children.
     */
    _buildLineEvaluations: function(submissionLineId, latestOnly) {
        var line = new GlideRecord(this.LINE_TABLE);
        line.get(submissionLineId);

        var out = {
            submissionLineId: submissionLineId,
            lineOfBusiness: line.isValidRecord() ? String(line.getDisplayValue('line_of_business')) : ''
        };

        var gr = new GlideRecord(this.TABLE);
        gr.addQuery('submission_line', submissionLineId);
        if (latestOnly)
            gr.addQuery('active', true);
        gr.orderByDesc('version');
        gr.query();

        if (latestOnly) {
            out.latestVersion = gr.next() ? this._buildEvaluation(gr) : null;
        } else {
            var versions = [];
            while (gr.next())
                versions.push(this._buildEvaluation(gr));
            out.versions = versions;
        }
        return out;
    },

    /** One loa_evaluation row, nested with its loa_evaluation_line children. */
    _buildEvaluation: function(gr) {
        var evaluation = {
            sysId: gr.getUniqueValue(),
            number: String(gr.getValue('number') || ''),
            version: parseInt(gr.getValue('version'), 10) || 0,
            isActive: String(gr.getValue('active')) === 'true',
            evaluationStatus: gr.getDisplayValue('evaluation_status'),
            evaluationStatusCode: String(gr.getValue('evaluation_status') || ''),
            evaluationTrigger: gr.getDisplayValue('evaluation_trigger'),
            evaluationTriggerCode: String(gr.getValue('evaluation_trigger') || ''),
            evaluatedOn: String(gr.getValue('evaluated_on') || ''),
            evaluatedUnderwriter: gr.getDisplayValue('evaluated_underwriter'),
            authorityTier: gr.getDisplayValue('authority_tier'),
            authorityTierCode: String(gr.getValue('authority_tier_code') || ''),
            isAuthorized: String(gr.getValue('is_authorized')) === 'true',
            requiresReferral: String(gr.getValue('requires_referral')) === 'true',
            referredToTier: gr.getDisplayValue('referred_to_tier'),
            message: String(gr.getValue('message') || ''),
            checksCount: parseInt(gr.getValue('checks_count'), 10) || 0,
            breachCount: parseInt(gr.getValue('breach_count'), 10) || 0,
            maxUtilisationPercent: gr.getValue('max_utilisation_percent'),
            decidedBy: gr.getDisplayValue('decided_by'),
            decidedOn: String(gr.getValue('decided_on') || ''),
            decisionNotes: String(gr.getValue('decision_notes') || ''),
            createdOn: String(gr.getValue('sys_created_on') || ''),
            evaluationLines: []
        };

        var l = new GlideRecord('x_gegis_ins_policy_loa_evaluation_line');
        l.addQuery('evaluation', gr.getUniqueValue());
        l.orderBy('sequence');
        l.query();
        while (l.next())
            evaluation.evaluationLines.push({
                sysId: l.getUniqueValue(),
                metricLabel: String(l.getDisplayValue('metric') || ''),
                exposureAmount: l.getValue('exposure_amount'),
                exposureCount: parseInt(l.getValue('exposure_count'), 10) || 0,
                limitAmountSnapshot: l.getValue('limit_amount_snapshot'),
                limitCountSnapshot: parseInt(l.getValue('limit_count_snapshot'), 10) || 0,
                utilisationPercent: l.getValue('utilisation_percent'),
                result: l.getDisplayValue('result'),
                resultCode: String(l.getValue('result') || ''),
                breachAmount: l.getValue('breach_amount'),
                breachReason: String(l.getValue('breach_reason') || ''),
                currency: String(l.getValue('currency') || '')
            });
        return evaluation;
    },

    type: 'LOAEvaluationVersionService'
};
